def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after '+')
        if '+' in v:
            version_part, _ = v.split('+', 1)
        else:
            version_part = v

        # Split off pre-release (after '-')
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Pre-release with identifiers
        key = [0]  # 0 indicates has pre-release
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers compare numerically and sort before non-digit
                key.append((0, int(identifier)))
            else:
                # Non-digit identifiers compare by ASCII order
                key.append((1, identifier))
        return tuple(key)

    # Parse all versions with their original index for stable sort
    parsed = []
    for idx, v in enumerate(versions):
        major, minor, patch, prerelease_ids = parse_version(v)
        sort_key = (major, minor, patch, prerelease_key(prerelease_ids), idx)
        parsed.append((sort_key, v))

    # Sort by the key
    parsed.sort(key=lambda x: x[0])

    # Return just the version strings
    return [v for _, v in parsed]

